// Generated by scripts/sync-core.mjs from mobile/src/state/scan.ts; edit it there and run npm run sync-core.
// The user's activity as a scan of a range of blocks: which events in them
// touch the user's accounts or IDs. The range grows forward with each new block
// and backward when older history is asked for, so no block is read twice, and
// it is saved on the device between runs. Pure: no React, no storage, no node.
import { equal, hex, unhex } from '@/core/chain/bytes';
import * as coin from '@/core/chain/coin';
import * as idp from '@/core/chain/identity';
import type { BlockEvents } from '@/core/chain/node';
import type { ActivityItem } from './chain';

/** What a scan looks for: everything of one user on one chain, whichever screen shows it. */
export interface ScanScope {
  chainId: Uint8Array;
  registry: Uint8Array;
  accounts: Uint8Array[];
  ids: Uint8Array[];
}

/** A found event as saved: height, transaction, contract, payload, whether it paid a fee or tip, and its block's time. */
export type SavedItem = [height: number, transaction: string, contract: string, payload: string, fee: 0 | 1, time: number];

/** A scan as saved: blocks `low` to `high` are read, and `tip` is the id of block `high` when known. */
export interface SavedScan {
  v: 2;
  low: number;
  high: number;
  tip: string;
  /** Oldest first. */
  items: SavedItem[];
}

/** Blocks a reorganization is assumed to reach at most: read again when the tip changed. */
export const REORG_DEPTH = 20;

export function scopeKey(s: ScanScope): string {
  const sorted = (xs: Uint8Array[]) => xs.map(hex).sort().join(',');
  return `${hex(s.chainId)}:${hex(s.registry)}:${sorted(s.accounts)}:${sorted(s.ids)}`;
}

export function touches(event: coin.CoinEvent | idp.IdEvent, accounts: Uint8Array[], ids: Uint8Array[]): boolean {
  const any = (x: Uint8Array, set: Uint8Array[]) => set.some((s) => equal(s, x));
  switch (event.kind) {
    case 'transfer':
      return any(event.from, accounts) || any(event.to, accounts);
    case 'scheduled':
    case 'executed':
    case 'cancelled':
      return any(event.account, accounts);
    case 'producerPayment':
      return any(event.payee, accounts);
    case 'minter':
      return false;
    default:
      return any(event.id, ids) || ('guardian' in event && any(event.guardian, ids));
  }
}

/**
 * The events of some blocks that touch the scope: identity events of the
 * registry, and events of any contract that read as coin events, so a coin the
 * user does not follow yet is found too. A zero transfer of an account to
 * itself only carries a fee bound to a batch and is left out. Each keeps its
 * block's time.
 */
export function matchBlocks(blocks: BlockEvents[], scope: ScanScope): SavedItem[] {
  const out: SavedItem[] = [];
  const item = (b: BlockEvents, e: BlockEvents['events'][number], fee: 0 | 1): SavedItem => [b.height, e.transaction, hex(e.contract), hex(e.payload), fee, b.time];
  for (const b of blocks) {
    for (const [i, e] of b.events.entries()) {
      if (equal(e.contract, scope.registry)) {
        const ev = idp.decodeIdEvent(e.payload);
        if (ev && touches(ev, scope.accounts, scope.ids)) out.push(item(b, e, 0));
        continue;
      }
      const ev = coin.decodeCoinEvent(e.payload);
      if (!ev || !touches(ev, scope.accounts, scope.ids)) continue;
      if (ev.kind === 'transfer' && ev.amount === 0n && equal(ev.from, ev.to)) continue;
      // A fee or tip is a transfer followed by its producer payment.
      let fee = false;
      const next = b.events[i + 1];
      if (ev.kind === 'transfer' && next && next.transaction === e.transaction && equal(next.contract, e.contract)) {
        const paid = coin.decodeCoinEvent(next.payload);
        fee = paid?.kind === 'producerPayment' && equal(paid.payee, ev.to) && paid.amount === ev.amount;
      }
      out.push(item(b, e, fee ? 1 : 0));
    }
  }
  return out;
}

/** A scan that has read nothing yet, about to read back from `height`. */
export function emptyScan(height: number): SavedScan {
  return { v: 2, low: height + 1, high: height, tip: '', items: [] };
}

/** Blocks read forward, `from` the block after `high` (or `high` itself, to see the tip is unchanged). */
export function addNewer(scan: SavedScan, blocks: BlockEvents[], scope: ScanScope): SavedScan {
  const fresh = blocks.filter((b) => b.height > scan.high);
  if (fresh.length === 0) return scan;
  const last = fresh[fresh.length - 1];
  return { ...scan, high: last.height, tip: last.block, items: [...scan.items, ...matchBlocks(fresh, scope)] };
}

/** Blocks read backward: the ones just below `low`, ending at `low - 1`. */
export function addOlder(scan: SavedScan, blocks: BlockEvents[], scope: ScanScope): SavedScan {
  const older = blocks.filter((b) => b.height < scan.low);
  if (older.length === 0) return scan;
  const tipBlock = older.find((b) => b.height === scan.high);
  return {
    ...scan,
    low: older[0].height,
    tip: tipBlock ? tipBlock.block : scan.tip,
    items: [...matchBlocks(older, scope), ...scan.items],
  };
}

/** Forgets the blocks above `height`, to read them again after a reorganization. */
export function rollBack(scan: SavedScan, height: number): SavedScan {
  const high = Math.max(height, scan.low - 1);
  return { ...scan, high, tip: '', items: scan.items.filter((it) => it[0] <= high) };
}

/**
 * The scan as kept on the device: at most `keep` items, the newest, cut at a
 * block boundary so that the blocks below `low` hold everything left out.
 */
export function trimmed(scan: SavedScan, keep: number): SavedScan {
  if (scan.items.length <= keep) return scan;
  const cut = scan.items[scan.items.length - keep - 1][0];
  return { ...scan, low: cut + 1, items: scan.items.filter((it) => it[0] > cut) };
}

/**
 * Saved items as activity, newest first, with each scheduled action marked
 * when a later event ran or cancelled it. A fee joins the other event of its
 * transaction, the one it paid for; only a fee paid for nothing else shown
 * stays an item of its own.
 */
export function activityOf(items: SavedItem[], registry: Uint8Array): ActivityItem[] {
  const out: ActivityItem[] = [];
  const scheduled = new Map<string, ActivityItem>();
  const actionKey = (contract: string, account: Uint8Array, sequence: bigint) => `${contract}:${hex(account)}:${sequence}`;
  const registryHex = hex(registry);
  for (const [height, transaction, contractHex, payloadHex, fee, time] of items) {
    const contract = unhex(contractHex);
    const payload = unhex(payloadHex);
    if (contractHex === registryHex) {
      const identity = idp.decodeIdEvent(payload);
      if (identity) out.push({ height, time, transaction, contract, identity });
      continue;
    }
    const ev = coin.decodeCoinEvent(payload);
    if (!ev) continue;
    const item: ActivityItem = { height, time, transaction, contract, coin: ev, fee: fee === 1 || undefined };
    if (ev.kind === 'scheduled') scheduled.set(actionKey(contractHex, ev.account, ev.sequence), item);
    if (ev.kind === 'executed' || ev.kind === 'cancelled') {
      const origin = scheduled.get(actionKey(contractHex, ev.account, ev.sequence));
      if (origin) origin.settled = ev.kind;
    }
    out.push(item);
  }
  const paidFor = new Map<string, ActivityItem>();
  for (const it of out) if (!it.fee && !paidFor.has(it.transaction)) paidFor.set(it.transaction, it);
  const kept = out.filter((it) => {
    const owner = it.fee && it.coin?.kind === 'transfer' ? paidFor.get(it.transaction) : undefined;
    if (!owner || it.coin?.kind !== 'transfer') return true;
    (owner.fees ??= []).push({ contract: it.contract, amount: it.coin.amount });
    return false;
  });
  return kept.reverse();
}

/** Whether a saved scan is one this version reads; an older one, saved without times, is read again from the chain. */
export function isSavedScan(v: unknown): v is SavedScan {
  const s = v as SavedScan;
  return !!s && s.v === 2 && Number.isInteger(s.low) && Number.isInteger(s.high) && typeof s.tip === 'string' && Array.isArray(s.items);
}
